def test_abaco2_similar_inverse_match():
    fx = f(x)
    xi = Function('xi')(x, fx)
    eta = Function('eta')(x, fx)

    # Direct ODE: h = x + exp(y)
    assert infinitesimals(
        fx.diff(x) - x - exp(fx), fx,
        hint='abaco2_similar'
    ) == [{
        xi: exp(-x**2/2),
        eta: x*exp(-x**2/2),
